command:
// Foundry VTT Macro: Валидация магии (смоук-тест Магического Конструктора)
// Прогоняет эталонные сборки через SpellCalculator и сверяет стоимости/ошибки.
// Запускать ГМом после любых правок src/config/magic.mjs или spell-calculator.mjs.
// Покрытие: Лестница урона (пиро-сдвиг, изобильный +1 ступень), доктринные
// модификаторы (владение, капы), формы по доктринам, пути-таланты, Насыщение,
// ignoresSource (Биомантия), запреты Областей (Тень/Био), удалённые дефолтные ранги.
// Плюс проверка целостности данных: каждый ключ состояния из конфига обязан
// резолвиться в предмет-состояние компендиума (CONFIG.statusEffects) — без неё
// мёртвые ключи (`poisoned`, `rage` до 2026-09-10) живут в конфиге незамеченными,
// потому что арифметика калькулятора на них не спотыкается.
(async () => {
  const Calc = game.dedrel?.SpellCalculator;
  if (!Calc) return ui.notifications.error("game.dedrel.SpellCalculator не найден. Система загружена?");

  const ALL_TECH = { create: 1, move: 1, transform: 1, sense: 1, imbue: 1 };
  const ALL_PATHS = { flow: 1, ice: 1, squall: 1, echo: 1, mending: 1, sculpting: 1 };

  // expect.errors — коды, которые ОБЯЗАНЫ присутствовать (порядок не важен);
  // expect.totalAp / requiredRank / check — проверки для валидных сборок.
  const cases = [
    // --- Лестница урона ---
    {
      name: "Пиро: сдвиг Лестницы (damage 2 → ступень IV, 2d8[heat])",
      build: { doctrine: "pyromancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "damage", rank: 2 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH },
      expect: { valid: true, totalAp: 3, check: r => r.compiled.system.formula_damage === "2d8[heat]" ? null : `formula: ${r.compiled.system.formula_damage}` }
    },
    {
      name: "Пиро: огненный шар (create + range 2 + damage 3 → 3d6[heat], дальность 10 м)",
      build: { doctrine: "pyromancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "range", rank: 2 }, { key: "damage", rank: 3 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH },
      expect: { valid: true, totalAp: 6, requiredRank: 3, check: r => r.compiled.system.formula_damage === "3d6[heat]" && r.compiled.system.target_range === "10" ? null : `formula/range: ${r.compiled.system.formula_damage} / ${r.compiled.system.target_range}` }
    },
    {
      name: "Пиро 5 в изобилии: damage 5 — кап ступенью VII (4d8, сдвиг+изобилие не выше)",
      build: { doctrine: "pyromancy", sourceScale: "abundant", techniques: ["create"], modifiers: [{ key: "damage", rank: 5 }] },
      context: { doctrineRank: 5, knownTechniques: ALL_TECH, abundantMode: "unlockAll" },
      expect: { valid: true, totalAp: 6, check: r => r.compiled.system.formula_damage === "4d8[heat]" ? null : `formula: ${r.compiled.system.formula_damage}` }
    },
    {
      name: "Гео в изобилии: изобильный источник поднимает урон на ступень (damage 1 → 2d6)",
      build: { doctrine: "geomancy", sourceScale: "abundant", techniques: ["move"], modifiers: [{ key: "damage", rank: 1 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH, abundantMode: "unlockAll" },
      expect: { valid: true, totalAp: 2, check: r => r.compiled.system.formula_damage === "2d6" ? null : `formula: ${r.compiled.system.formula_damage}` }
    },
    {
      name: "Венто-Эхо: звуковой урон по обычной Лестнице (damage 2 → 2d6[sonic], +1 ОД налог доктрины)",
      build: { doctrine: "ventomancy", path: "echo", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "damage", rank: 2 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: true, totalAp: 5, check: r => r.compiled.system.formula_damage === "2d6[sonic]" ? null : `formula: ${r.compiled.system.formula_damage}` }
    },

    // --- Лимиты рангов и источник ---
    {
      name: "Гео 3: урон ранга 4 — превышение maxModCost (пример из правил)",
      build: { doctrine: "geomancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "damage", rank: 4 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["over_max_mod_cost"] }
    },
    {
      name: "Гидро-Поток 2 в море (unlockAll): изобилие снимает лимит ранга (area_circle 5)",
      build: { doctrine: "hydromancy", path: "flow", sourceScale: "abundant", techniques: ["move"], modifiers: [{ key: "area_circle", rank: 5 }, { key: "damage", rank: 2 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS, abundantMode: "unlockAll" },
      expect: { valid: true, totalAp: 7, requiredRank: 1 }
      // move 1−1=0 + area_circle 5+1(надбавка Областей)−1(сродство Потока)=5 + damage 2 = 7
    },
    {
      name: "Гидро-Поток 2 в море (requireRank): 5-й ранг требует собственного Ранга 5",
      build: { doctrine: "hydromancy", path: "flow", sourceScale: "abundant", techniques: ["move"], modifiers: [{ key: "area_circle", rank: 5 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS, abundantMode: "requireRank" },
      expect: { valid: false, errors: ["over_max_mod_cost"] }
    },
    {
      name: "Гидро-Лёд 5 в море (requireRank): damage 5 → ступень VII (4d8)",
      build: { doctrine: "hydromancy", path: "ice", sourceScale: "abundant", techniques: ["move"], modifiers: [{ key: "damage", rank: 5 }] },
      context: { doctrineRank: 5, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS, abundantMode: "requireRank" },
      expect: { valid: true, totalAp: 6, requiredRank: 5, check: r => r.compiled.system.formula_damage === "4d8" ? null : `formula: ${r.compiled.system.formula_damage}` }
    },
    {
      name: "Направить без Источника — недоступно",
      build: { doctrine: "hydromancy", sourceScale: "none", techniques: ["move"], modifiers: [] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["technique_needs_source"] }
    },
    {
      name: "Неизученная техника",
      build: { doctrine: "pyromancy", sourceScale: "none", techniques: ["create"], modifiers: [] },
      context: { doctrineRank: 1, knownTechniques: {} },
      expect: { valid: false, errors: ["technique_not_known"] }
    },

    // --- Пути = таланты ---
    {
      name: "Путь Льда не изучен — сборка с путём нелегальна",
      build: { doctrine: "hydromancy", path: "ice", sourceScale: "any", techniques: ["move"], modifiers: [] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH, knownPaths: {} },
      expect: { valid: false, errors: ["path_not_known"] }
    },
    {
      name: "Гидромантия без пути — легальна всегда (сродств нет: move за 1)",
      build: { doctrine: "hydromancy", path: "", sourceScale: "any", techniques: ["move"], modifiers: [] },
      context: { doctrineRank: 1, knownTechniques: ALL_TECH, knownPaths: {} },
      expect: { valid: true, totalAp: 1, requiredRank: 1 }
    },
    {
      name: "Кламп нулём: Направить у Пути Потока стоит 0 ОД (сродство −1)",
      build: { doctrine: "hydromancy", path: "flow", sourceScale: "any", techniques: ["move"], modifiers: [] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: true, totalAp: 0, requiredRank: 1 }
    },
    {
      name: "Гидро-Поток: Прочность выше 2 ранга — кап пути",
      build: { doctrine: "hydromancy", path: "flow", sourceScale: "any", techniques: ["move"], modifiers: [{ key: "durability", rank: 3 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: false, errors: ["modifier_over_cap"] }
    },

    // --- Доктринные модификаторы: владение и капы ---
    {
      name: "Гео: «Сила» не принадлежит — modifier_not_owned",
      build: { doctrine: "geomancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "power", rank: 2 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["modifier_not_owned"] }
    },
    {
      name: "Эхо: «Сила» ранга 4 — вне рангов Психоакустики (1–3)",
      build: { doctrine: "ventomancy", path: "echo", sourceScale: "none", techniques: ["imbue"], modifiers: [{ key: "power", rank: 4 }] },
      context: { doctrineRank: 4, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: false, errors: ["modifier_rank_not_allowed"] }
    },
    {
      name: "Эхо: Сила 3 со состоянием — спасбросок 14, кондиция fear (штраф/состояние)",
      build: { doctrine: "ventomancy", path: "echo", sourceScale: "none", techniques: ["imbue"], modifiers: [{ key: "power", rank: 3, option: "fear" }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: true, totalAp: 3, check: r => r.compiled.system.save_dc_formula === "14" && r.compiled.extras.appliedConditions.includes("fear") ? null : `save/conditions: ${r.compiled.system.save_dc_formula} / ${r.compiled.extras.appliedConditions}` }
      // imbue 1 + power 3 − сродство Эха на Силу 1 = 3
    },
    {
      name: "Эхо: Сила 2 — чистый штраф −2 (бонусных ветвей нет)",
      build: { doctrine: "ventomancy", path: "echo", sourceScale: "none", techniques: ["imbue"], modifiers: [{ key: "power", rank: 2, option: "penalty" }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: true, totalAp: 2, check: r => r.compiled.extras.powerBonus === -2 ? null : `powerBonus: ${r.compiled.extras.powerBonus}` }
    },
    {
      name: "Эхо: «Долгая песня» — Насыщение 2 на 6 раундов, Длительность со скидкой Пути",
      build: { doctrine: "ventomancy", path: "echo", sourceScale: "none", techniques: ["imbue"], modifiers: [{ key: "imbuement", rank: 2 }, { key: "duration", rank: 2 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      // imbue 1 + Насыщение 2 + Длительность (2 − 1 сродство Эха) = 4
      expect: { valid: true, totalAp: 4, check: r => r.compiled.extras.durationRounds === 6 && r.compiled.extras.imbue?.value === 2 ? null : `rounds/imbue: ${r.compiled.extras.durationRounds} / ${r.compiled.extras.imbue?.value}` }
    },
    {
      name: "Венто: Сбивание 2 — prone, СЛ 12 (доктринный модификатор базы)",
      build: { doctrine: "ventomancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "knockdown", rank: 2 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH },
      expect: { valid: true, totalAp: 4, check: r => r.compiled.system.save_dc_formula === "12" && r.compiled.extras.appliedConditions.includes("prone") ? null : `save/cond: ${r.compiled.system.save_dc_formula} / ${r.compiled.extras.appliedConditions}` }
    },
    {
      name: "Венто: Пыльная завеса без Области — modifier_needs_area",
      build: { doctrine: "ventomancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "dust_veil", rank: 2 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["modifier_needs_area"] }
    },
    {
      name: "Лёд: Сковывание 3 — entangled, СЛ 14",
      build: { doctrine: "hydromancy", path: "ice", sourceScale: "any", techniques: ["move"], modifiers: [{ key: "constrain", rank: 3 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: true, totalAp: 4, check: r => r.compiled.system.save_dc_formula === "14" && r.compiled.extras.appliedConditions.includes("entangled") ? null : `save/cond: ${r.compiled.system.save_dc_formula} / ${r.compiled.extras.appliedConditions}` }
    },
    {
      name: "Тенемантия: полный каталог «Силы» (ранг 5 в изобилии, состояние terror)",
      build: { doctrine: "shadowmancy", sourceScale: "abundant", techniques: ["move"], modifiers: [{ key: "power", rank: 5, option: "terror" }] },
      context: { doctrineRank: 5, knownTechniques: ALL_TECH, abundantMode: "requireRank" },
      expect: { valid: true, totalAp: 6, check: r => r.compiled.system.save_dc_formula === "18" && r.compiled.extras.appliedConditions.includes("terror") ? null : `save/cond: ${r.compiled.system.save_dc_formula} / ${r.compiled.extras.appliedConditions}` }
    },
    {
      name: "Тенемантия: «Увядание» — своё состояние ранга 4 (СЛ 16)",
      build: { doctrine: "shadowmancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "power", rank: 4, option: "withering" }] },
      context: { doctrineRank: 4, knownTechniques: ALL_TECH },
      expect: { valid: true, totalAp: 6, requiredRank: 4, check: r => r.compiled.system.save_dc_formula === "16" && r.compiled.extras.appliedConditions.includes("withering") ? null : `save/cond: ${r.compiled.system.save_dc_formula} / ${r.compiled.extras.appliedConditions}` }
      // create 2 + power 4 = 6
    },
    {
      name: "Эхо не дотягивается до «Увядания» (Сила ранга 4 капнута рангами 1–3)",
      build: { doctrine: "ventomancy", path: "echo", sourceScale: "none", techniques: ["imbue"], modifiers: [{ key: "power", rank: 4 }] },
      context: { doctrineRank: 4, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: false, errors: ["modifier_rank_not_allowed"] }
    },
    {
      name: "Тенемантия: сродство на Длительность (−1) и штраф на Урон (+1)",
      build: { doctrine: "shadowmancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "damage", rank: 2 }, { key: "duration", rank: 2 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH },
      expect: { valid: true, totalAp: 6, check: r => r.compiled.system.formula_damage === "2d6[necrotic]" ? null : `formula: ${r.compiled.system.formula_damage}` }
      // create 2 + damage 2+1=3 + duration 2−1=1 = 6
    },

    // --- Формы по доктринам ---
    {
      name: "Пиро: Форма недоступна (форм нет — чистое тепло)",
      build: { doctrine: "pyromancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "form", rank: 2 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["modifier_forbidden"] }
    },
    {
      name: "Форма: ранги 3–5 удалены (плоская цена 2 ОД)",
      build: { doctrine: "geomancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "form", rank: 3 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["modifier_rank_unavailable"] }
    },
    {
      name: "Гидро-Лёд: Форма за 1 ОД (сродство), тип из списка пути (piercing)",
      build: { doctrine: "hydromancy", path: "ice", sourceScale: "any", techniques: ["move"], modifiers: [{ key: "form", rank: 2, option: "piercing" }, { key: "damage", rank: 1 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: true, totalAp: 3, check: r => r.compiled.system.formula_damage === "2d4[piercing]" ? null : `formula: ${r.compiled.system.formula_damage}` }
    },

    // --- Насыщение ---
    {
      name: "Насыщение без техники Насытить — modifier_needs_technique",
      build: { doctrine: "geomancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "imbuement", rank: 1 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["modifier_needs_technique"] }
    },
    {
      name: "Гео: Насытить (0 ОД, сродство) + Насыщение 2 (DR) = 2 ОД",
      build: { doctrine: "geomancy", sourceScale: "none", techniques: ["imbue"], modifiers: [{ key: "imbuement", rank: 2, option: "dr" }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH },
      expect: { valid: true, totalAp: 2, check: r => r.compiled.extras.imbue?.value === 2 && r.compiled.extras.imbue?.option === "dr" ? null : `imbue: ${JSON.stringify(r.compiled.extras.imbue)}` }
    },

    {
      name: "Гидро без пути: Форма с выбором из двух (2d4[slashing])",
      build: { doctrine: "hydromancy", sourceScale: "any", techniques: ["move"], modifiers: [{ key: "form", rank: 2, option: "slashing" }, { key: "damage", rank: 1 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH },
      expect: { valid: true, totalAp: 4, check: r => r.compiled.system.formula_damage === "2d4[slashing]" ? null : `formula: ${r.compiled.system.formula_damage}` }
    },

    // --- Биомантия (ignoresSource) ---
    {
      name: "Биомантия: Направить без Источника — доступна (ignoresSource)",
      build: { doctrine: "biomancy", sourceScale: "none", techniques: ["move"], modifiers: [{ key: "heal", rank: 1 }] },
      context: { doctrineRank: 1, knownTechniques: ALL_TECH },
      expect: { valid: true, totalAp: 2 }
    },
    {
      name: "Биомантия 5: 5-й ранг Лечения без изобилия (гейт — Ранг Доктрины; Путь снимает кап, сродство −1 ОД)",
      build: { doctrine: "biomancy", path: "mending", sourceScale: "none", techniques: ["move"], modifiers: [{ key: "heal", rank: 5 }] },
      context: { doctrineRank: 5, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: true, totalAp: 5, requiredRank: 5, check: r => r.compiled.system.formula_heal === "3d8" ? null : `heal: ${r.compiled.system.formula_heal}` }
    },
    {
      name: "Биомантия 4: 5-й ранг закрыт maxModCost (ignoresSource ≠ изобилие)",
      build: { doctrine: "biomancy", path: "mending", sourceScale: "none", techniques: ["move"], modifiers: [{ key: "heal", rank: 5 }] },
      context: { doctrineRank: 4, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: false, errors: ["over_max_mod_cost"] }
    },
    {
      name: "Биомантия: Урон запрещён целиком (конституция доктрины)",
      build: { doctrine: "biomancy", sourceScale: "none", techniques: ["transform"], modifiers: [{ key: "damage", rank: 1 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["modifier_forbidden"] }
    },
    {
      name: "Биомантия: Лечение 3 → formula_heal 2d8",
      build: { doctrine: "biomancy", sourceScale: "none", techniques: ["transform"], modifiers: [{ key: "heal", rank: 3 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH },
      expect: { valid: true, totalAp: 4, check: r => r.compiled.system.formula_heal === "2d8" ? null : `heal: ${r.compiled.system.formula_heal}` }
    },
    {
      name: "Биомантия: техника «Создать» запрещена (плоть не творится из ниоткуда)",
      build: { doctrine: "biomancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "heal", rank: 1 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH, knownPaths: {} },
      expect: { valid: false, errors: ["technique_forbidden"] }
    },
    {
      name: "Биомантия: «Почуять» доступна (искать следы ваяния)",
      build: { doctrine: "biomancy", sourceScale: "none", techniques: ["sense"], modifiers: [] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH, knownPaths: {} },
      expect: { valid: true }
    },
    // --- Пути Биомантии (2026-09-11): Врачевание / Ваяние ---
    {
      name: "Биомантия без Пути: Лечение 4 упирается в кап доктрины (1-3)",
      build: { doctrine: "biomancy", sourceScale: "none", techniques: ["move"], modifiers: [{ key: "heal", rank: 4 }] },
      context: { doctrineRank: 5, knownTechniques: ALL_TECH, knownPaths: {} },
      expect: { valid: false, errors: ["modifier_over_cap"] }
    },
    {
      name: "Биомантия без Пути: Адаптация 4 упирается в кап доктрины (1-3)",
      build: { doctrine: "biomancy", sourceScale: "none", techniques: ["transform"], modifiers: [{ key: "adapt", rank: 4 }] },
      context: { doctrineRank: 5, knownTechniques: ALL_TECH, knownPaths: {} },
      expect: { valid: false, errors: ["modifier_over_cap"] }
    },
    {
      name: "Биомантия без Пути: Дальность 3 запрещена (доктрина контактна, кап 2)",
      build: { doctrine: "biomancy", sourceScale: "none", techniques: ["move"], modifiers: [{ key: "heal", rank: 1 }, { key: "range", rank: 3 }] },
      context: { doctrineRank: 5, knownTechniques: ALL_TECH, knownPaths: {} },
      expect: { valid: false, errors: ["modifier_over_cap"] }
    },
    {
      name: "Врачевание: Дальность 2 доступна (дотянуться через строй)",
      build: { doctrine: "biomancy", path: "mending", sourceScale: "none", techniques: ["move"], modifiers: [{ key: "heal", rank: 1 }, { key: "range", rank: 2 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: true }
    },
    {
      name: "Врачевание: Адаптация 4 всё ещё закрыта (кап доктрины не снят)",
      build: { doctrine: "biomancy", path: "mending", sourceScale: "none", techniques: ["transform"], modifiers: [{ key: "adapt", rank: 4 }] },
      context: { doctrineRank: 5, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: false, errors: ["modifier_over_cap"] }
    },
    {
      name: "Ваяние: Адаптация 5 открыта Путём",
      build: { doctrine: "biomancy", path: "sculpting", sourceScale: "none", techniques: ["transform"], modifiers: [{ key: "adapt", rank: 5 }] },
      context: { doctrineRank: 5, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: true, requiredRank: 5 }
    },
    {
      name: "Ваяние: Дальность 2 запрещена — только касание",
      build: { doctrine: "biomancy", path: "sculpting", sourceScale: "none", techniques: ["transform"], modifiers: [{ key: "adapt", rank: 1 }, { key: "range", rank: 2 }] },
      context: { doctrineRank: 5, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: false, errors: ["modifier_over_cap"] }
    },
    {
      name: "Ваяние: Дальность 1 (касание) проходит",
      build: { doctrine: "biomancy", path: "sculpting", sourceScale: "none", techniques: ["transform"], modifiers: [{ key: "adapt", rank: 1 }, { key: "range", rank: 1 }] },
      context: { doctrineRank: 5, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: true }
    },
    {
      name: "Ваяние: Лечение 4 закрыто (кап Пути — 3)",
      build: { doctrine: "biomancy", path: "sculpting", sourceScale: "none", techniques: ["move"], modifiers: [{ key: "heal", rank: 4 }] },
      context: { doctrineRank: 5, knownTechniques: ALL_TECH, knownPaths: ALL_PATHS },
      expect: { valid: false, errors: ["modifier_over_cap"] }
    },
    {
      name: "Биомантия: Путь не изучен — сборка на нём невалидна",
      build: { doctrine: "biomancy", path: "sculpting", sourceScale: "none", techniques: ["transform"], modifiers: [{ key: "adapt", rank: 1 }] },
      context: { doctrineRank: 5, knownTechniques: ALL_TECH, knownPaths: {} },
      expect: { valid: false, errors: ["path_not_known"] }
    },
    {
      name: "Биомантия: Области запрещены (таргетная доктрина)",
      build: { doctrine: "biomancy", sourceScale: "none", techniques: ["transform"], modifiers: [{ key: "area_cone", rank: 2 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["modifier_forbidden"] }
    },
    {
      name: "Тенемантия: Области запрещены (таргетная доктрина)",
      build: { doctrine: "shadowmancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "area_circle", rank: 2 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["modifier_forbidden"] }
    },

    // --- Удалённые дефолтные ранги, взаимоисключения, прочее ---
    {
      name: "Цели ранга 1 удалены (одна цель — дефолт)",
      build: { doctrine: "geomancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "targets", rank: 1 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["modifier_rank_unavailable"] }
    },
    {
      name: "Длительность ранга 1 удалена (мгновенно — дефолт)",
      build: { doctrine: "geomancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "duration", rank: 1 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["modifier_rank_unavailable"] }
    },
    {
      name: "Цели + Область: площадь — несовместимы",
      build: { doctrine: "geomancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "targets", rank: 2 }, { key: "area_circle", rank: 2 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["modifier_conflict"] }
    },
    {
      name: "Конус + Дальность — Дальность неприменима; конус в метрах (длина 8)",
      build: { doctrine: "ventomancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "area_cone", rank: 3 }, { key: "range", rank: 2 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["cone_no_range"] }
    },
    {
      name: "Область дороже ранга (+1 ОД): радиус 4 м = ранг 3, цена 4 ОД (template_size = 4)",
      build: { doctrine: "ventomancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "area_circle", rank: 3 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH },
      expect: { valid: true, totalAp: 6, check: r => r.compiled.system.template_size === 4 && r.compiled.system.template_shape === "circle" ? null : `template: ${r.compiled.system.template_shape} ${r.compiled.system.template_size}` }
      // create 2 + area_circle 3+1 = 6; надбавка Областей НЕ влияет на maxModCost (гейт по рангу)
    },
    {
      name: "Пиро: неблокируемый шар (forbidDefense 4, опция по умолчанию = block)",
      build: { doctrine: "pyromancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "damage", rank: 2 }, { key: "forbidDefense", rank: 4 }] },
      context: { doctrineRank: 4, knownTechniques: ALL_TECH },
      expect: { valid: true, totalAp: 7, requiredRank: 4, check: r => r.compiled.system.forbidden_defense === "block" ? null : `forbidden_defense: ${r.compiled.system.forbidden_defense}` }
    },
    {
      name: "Пиро: штраф на Точность (+1 ОД) и скидка на Урон (−1 ОД)",
      build: { doctrine: "pyromancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "damage", rank: 2 }, { key: "accuracy", rank: 1 }] },
      context: { doctrineRank: 3, knownTechniques: ALL_TECH },
      expect: { valid: true, totalAp: 5, check: r => r.compiled.system.attack_bonus === 1 ? null : `attack_bonus: ${r.compiled.system.attack_bonus}` }
    },
    {
      name: "Лимит количества: 3 модификатора на ранге 2",
      build: { doctrine: "geomancy", sourceScale: "none", techniques: ["create"], modifiers: [{ key: "range", rank: 1 }, { key: "damage", rank: 1 }, { key: "duration", rank: 2 }] },
      context: { doctrineRank: 2, knownTechniques: ALL_TECH },
      expect: { valid: false, errors: ["too_many_modifiers"] }
    }
  ];

  // --- Целостность данных: ключи состояний из конфига → реестр статусов ---
  // Реестр собирается из компендиумов на старте мира (dedrel.mjs
  // rebuildStatusEffects). Ключ без предмета = селект покажет сырую латиницу,
  // а кнопка «Наложить» в карточке ничего не наложит.
  const danglingConditions = [];
  const magicCfg = CONFIG.DEDREL?.magic;
  for (const [modKey, modCfg] of Object.entries(magicCfg?.modifiers ?? {})) {
    for (const [rank, rankCfg] of Object.entries(modCfg.ranks ?? {})) {
      for (const condKey of rankCfg.conditions ?? []) {
        if (!CONFIG.statusEffects[condKey]) danglingConditions.push(`${modKey} ${rank} → ${condKey}`);
      }
    }
  }

  const rows = [];
  let passed = 0;

  const condOk = danglingConditions.length === 0;
  if (condOk) passed++;
  rows.push(`<tr><td style="color:${condOk ? "green" : "red"};font-weight:bold;">${condOk ? "PASS" : "FAIL"}</td>`
    + `<td>Состояния конфига есть в компендиумах`
    + `${condOk ? "" : `<br><small>нет предмета: ${danglingConditions.join("; ")}</small>`}</td></tr>`);
  if (!condOk) console.warn("Dedrel | Валидация магии: состояния без предметов", danglingConditions);

  for (const c of cases) {
    const r = Calc.calculate(c.build, c.context);
    const problems = [];
    if (r.valid !== c.expect.valid) problems.push(`valid: ${r.valid}, ожидалось ${c.expect.valid}`);
    if (c.expect.totalAp !== undefined && r.totalAp !== c.expect.totalAp) problems.push(`totalAp: ${r.totalAp}, ожидалось ${c.expect.totalAp}`);
    if (c.expect.requiredRank !== undefined && r.requiredRank !== c.expect.requiredRank) problems.push(`requiredRank: ${r.requiredRank}, ожидалось ${c.expect.requiredRank}`);
    for (const code of c.expect.errors || []) {
      if (!r.errors.some(e => e.code === code)) problems.push(`нет ожидаемой ошибки "${code}" (получены: ${r.errors.map(e => e.code).join(", ") || "нет"})`);
    }
    if (c.expect.check && r.valid && r.compiled) {
      const msg = c.expect.check(r);
      if (msg) problems.push(msg);
    }
    const ok = problems.length === 0;
    if (ok) passed++;
    rows.push(`<tr><td style="color:${ok ? "green" : "red"};font-weight:bold;">${ok ? "PASS" : "FAIL"}</td><td>${c.name}${ok ? "" : `<br><small>${problems.join("; ")}</small>`}</td></tr>`);
    if (!ok) console.warn(`Dedrel | Валидация магии FAIL: ${c.name}`, { result: r, problems });
  }

  const total = cases.length + 1; // +1 — проверка целостности состояний
  const content = `
    <h3>Валидация магии: ${passed}/${total}</h3>
    <table style="width:100%;font-size:12px;"><tbody>${rows.join("")}</tbody></table>
  `;
  await ChatMessage.create({ user: game.user.id, content, whisper: [game.user.id] });
  ui.notifications[passed === total ? "info" : "error"](`Валидация магии: ${passed}/${total} тестов пройдено.`);
})();
